using UnityEngine;

namespace SameShore.EditorTools
{
    /// <summary>Textures and meshes generated by code (no external assets needed).</summary>
    public static class ProceduralArt
    {
        public static Texture2D RoundedRect(int size = 128, int radius = 28)
        {
            var t = new Texture2D(size, size, TextureFormat.RGBA32, false);
            for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
            {
                float dx = Mathf.Max(0, Mathf.Max(radius - x, x - (size - 1 - radius)));
                float dy = Mathf.Max(0, Mathf.Max(radius - y, y - (size - 1 - radius)));
                float d = Mathf.Sqrt(dx * dx + dy * dy);
                float a = Mathf.Clamp01(radius - d + 0.5f);
                t.SetPixel(x, y, new Color(1, 1, 1, a));
            }
            t.Apply();
            return t;
        }

        /// <summary>Bare-foot print: heel + sole + toes, soft edges. Alpha = depth.</summary>
        public static Texture2D Footprint(int w = 64, int h = 160)
        {
            var t = new Texture2D(w, h, TextureFormat.RGBA32, true);
            for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                float u = (x + 0.5f) / w * 2 - 1, v = (y + 0.5f) / h;
                float heel = Ellipse(u + 0.05f, v - 0.17f, 0.55f, 0.15f);
                float sole = Ellipse(u - 0.08f, v - 0.55f, 0.72f, 0.24f);
                float arch = Ellipse(u - 0.25f, v - 0.36f, 0.42f, 0.16f);
                float toes = 0;
                float[] tx = { -0.45f, -0.12f, 0.15f, 0.38f, 0.58f };
                float[] ty = { 0.86f, 0.9f, 0.88f, 0.84f, 0.79f };
                float[] tr = { 0.2f, 0.15f, 0.13f, 0.11f, 0.1f };
                for (int i = 0; i < 5; i++) toes = Mathf.Max(toes, Ellipse(u - tx[i], v - ty[i], tr[i], tr[i] * 0.4f));
                float a = Mathf.Max(Mathf.Max(heel, sole), Mathf.Max(arch * 0.8f, toes));
                float noise = Mathf.PerlinNoise(x * 0.3f, y * 0.3f) * 0.3f + 0.7f;
                t.SetPixel(x, y, new Color(1, 1, 1, Mathf.Clamp01(a * noise) * 0.85f));
            }
            t.Apply();
            return t;
        }

        static float Ellipse(float x, float y, float rx, float ry)
        {
            float d = Mathf.Sqrt((x / rx) * (x / rx) + (y / ry) * (y / ry));
            return Mathf.Clamp01((1.15f - d) * 3f);
        }

        /// <summary>Waxing crescent with soft halo.</summary>
        public static Texture2D Crescent(int size = 256)
        {
            var t = new Texture2D(size, size, TextureFormat.RGBA32, true);
            float r = 0.3f;
            for (int y = 0; y < size; y++)
            for (int x = 0; x < size; x++)
            {
                float u = (x + 0.5f) / size - 0.5f, v = (y + 0.5f) / size - 0.5f;
                float d = Mathf.Sqrt(u * u + v * v);
                float disc = Mathf.Clamp01((r - d) * size * 0.5f);
                float du = u + 0.13f, dv = v - 0.05f; // shadow disc offset -> crescent
                float shadow = Mathf.Clamp01((r * 0.95f - Mathf.Sqrt(du * du + dv * dv)) * size * 0.3f);
                float lit = disc * (1 - shadow);
                float tex = 0.85f + 0.15f * Mathf.PerlinNoise(u * 18 + 3, v * 18 + 7);
                float halo = Mathf.Exp(-Mathf.Max(0, d - r) * 14f) * 0.22f * (1 - disc) + disc * 0.02f;
                Color c = new Color(1f, 0.97f, 0.88f) * (lit * tex) + new Color(0.6f, 0.7f, 0.9f) * halo;
                c.a = Mathf.Clamp01(lit + halo * 1.5f);
                t.SetPixel(x, y, c);
            }
            t.Apply();
            return t;
        }

        /// <summary>Hotel facade at night: warm lit windows, some dark, some blue (TV).</summary>
        public static Texture2D HotelWindows(int cols = 16, int rows = 24, int cell = 16)
        {
            int w = cols * cell, h = rows * cell;
            var t = new Texture2D(w, h, TextureFormat.RGBA32, true);
            var rnd = new System.Random(4);
            Color wall = new Color(0.015f, 0.016f, 0.02f, 1);
            for (int cy = 0; cy < rows; cy++)
            for (int cx = 0; cx < cols; cx++)
            {
                double p = rnd.NextDouble();
                Color win = p < 0.45 ? new Color(0.02f, 0.02f, 0.03f) :
                            p < 0.85 ? new Color(1f, 0.72f, 0.38f) * (0.6f + (float)rnd.NextDouble() * 0.4f) :
                                       new Color(0.45f, 0.6f, 1f) * 0.6f;
                for (int y = 0; y < cell; y++)
                for (int x = 0; x < cell; x++)
                {
                    bool inWin = x > 3 && x < cell - 3 && y > 4 && y < cell - 2;
                    t.SetPixel(cx * cell + x, cy * cell + y, inWin ? win : wall);
                }
            }
            t.Apply();
            return t;
        }

        /// <summary>Hatchling crawl track: two rows of flipper scoops either side of a shallow drag line.</summary>
        public static Texture2D TurtleTrack(int w = 128, int h = 64)
        {
            var t = new Texture2D(w, h, TextureFormat.RGBA32, true) { wrapMode = TextureWrapMode.Clamp };
            for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                float u = (x + 0.5f) / w * 2 - 1, v = (y + 0.5f) / h;
                float drag = Mathf.Clamp01(1 - Mathf.Abs(u) / 0.12f) * 0.45f;
                float side = Mathf.Abs(u);
                float scoop = Mathf.Clamp01(1 - Mathf.Abs(side - 0.7f) / 0.16f) * Mathf.Clamp01(1 - Mathf.Abs(v - 0.5f) / 0.4f);
                float a = Mathf.Max(drag, scoop * 0.8f) * (0.8f + 0.2f * Mathf.PerlinNoise(x * 0.2f, y * 0.2f));
                t.SetPixel(x, y, new Color(1, 1, 1, a));
            }
            t.Apply();
            return t;
        }

        /// <summary>Soft ring (ground marker).</summary>
        public static Texture2D Ring(int n = 128)
        {
            var t = new Texture2D(n, n, TextureFormat.RGBA32, true) { wrapMode = TextureWrapMode.Clamp };
            for (int y = 0; y < n; y++)
            for (int x = 0; x < n; x++)
            {
                float u = (x + 0.5f) / n * 2 - 1, v = (y + 0.5f) / n * 2 - 1;
                float r = Mathf.Sqrt(u * u + v * v);
                t.SetPixel(x, y, new Color(1, 1, 1, Mathf.Clamp01(1 - Mathf.Abs(r - 0.82f) / 0.07f)));
            }
            t.Apply();
            return t;
        }

        /// <summary>Flat grid, denser near z=0 and growing towards +z (sea side) and the sides.</summary>
        public static Mesh OceanGrid(float halfWidth, float nearZ, float farZ, int cols, int rows)
        {
            var m = new Mesh { name = "OceanGrid", indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
            var v = new Vector3[(cols + 1) * (rows + 1)];
            for (int r = 0; r <= rows; r++)
            {
                float tz = r / (float)rows;
                float z = nearZ + (farZ - nearZ) * tz * tz * tz;
                for (int c = 0; c <= cols; c++)
                {
                    float tx = c / (float)cols * 2 - 1;
                    float x = Mathf.Sign(tx) * Mathf.Pow(Mathf.Abs(tx), 2.2f) * halfWidth;
                    v[r * (cols + 1) + c] = new Vector3(x, 0, z);
                }
            }
            var tri = new int[cols * rows * 6];
            int k = 0;
            for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
            {
                int i = r * (cols + 1) + c;
                tri[k++] = i; tri[k++] = i + cols + 1; tri[k++] = i + 1;
                tri[k++] = i + 1; tri[k++] = i + cols + 1; tri[k++] = i + cols + 2;
            }
            m.vertices = v;
            m.triangles = tri;
            m.RecalculateNormals();
            m.bounds = new Bounds(new Vector3(0, 0, (nearZ + farZ) / 2), new Vector3(halfWidth * 2, 4, farZ - nearZ));
            return m;
        }

        /// <summary>Strip along the shoreline, conformed to the terrain (for the swash shader).</summary>
        public static Mesh SwashStrip(System.Func<float, float, float> height, float x0, float x1, float zSea, float zLand, float step)
        {
            int cols = Mathf.CeilToInt((x1 - x0) / step), rows = Mathf.CeilToInt((zSea - zLand) / step);
            var m = new Mesh { name = "SwashStrip", indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
            var v = new Vector3[(cols + 1) * (rows + 1)];
            for (int r = 0; r <= rows; r++)
            for (int c = 0; c <= cols; c++)
            {
                float x = x0 + (x1 - x0) * c / cols;
                float z = zLand + (zSea - zLand) * r / rows;
                v[r * (cols + 1) + c] = new Vector3(x, height(x, z) + 0.025f, z);
            }
            var tri = new int[cols * rows * 6];
            int k = 0;
            for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
            {
                int i = r * (cols + 1) + c;
                tri[k++] = i; tri[k++] = i + cols + 1; tri[k++] = i + 1;
                tri[k++] = i + 1; tri[k++] = i + cols + 1; tri[k++] = i + cols + 2;
            }
            m.vertices = v;
            m.triangles = tri;
            m.RecalculateNormals();
            m.RecalculateBounds();
            return m;
        }
    }
}
